import {indiaEconomyData as data} from './india-economy-data.js?v=20261026-development03';
import {developmentPaths} from './development-data.js?v=20261026-development01';
export {data as indiaEconomyData};
export const indiaEconomyViews={
 'dev-india-context':[['institutions','Institutions and diversity'],['access','Access to opportunity'],['monsoon','Seasonal water'],['connections','Regional and global links']],
 'dev-india-regions':[['network','Concentrated advantage'],['evidence','Compare state evidence'],['spread','Spread and backwash'],['within','Look within regions']],
 'dev-india-sectors':[['classify','Four connected sectors'],['profile','Compare output shares'],['chain','Follow the supply chain'],['impacts','Weigh gains and costs']],
 'dev-india-trade-aid':[['exchange','Trade in both directions'],['flows','Proportional export flows'],['exports','Goods and services'],['aid','Development partnerships']],
 'dev-india-investment':[['history','Changing roles'],['evidence','Public spending plans'],['networks','Networks and firms'],['budget','Follow local spending']]
};
export const indiaEconomyRequirements=Object.fromEntries(Object.entries(indiaEconomyViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const indiaEconomyAnimated=(k,v)=>({'dev-india-context':['access','monsoon'],'dev-india-regions':['network','spread'],'dev-india-sectors':['chain'],'dev-india-trade-aid':['exchange','aid'],'dev-india-investment':['networks','budget']}[k]||[]).includes(v);
export const selectedStateMean=()=>data.regions.states.reduce((s,r)=>s+r[1],0)/data.regions.states.length;
export const tradeWidth=value=>value*.16;
export const localBudget={local:60,external:25,upkeep:15};
const fmt=n=>n.toLocaleString('en-GB');
const txt=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b5cbd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=5,c='#edb194')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f4e8d7"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#9ebdc7"/>`+txt(x+10,y+24,a,12)+(b?txt(x+10,y+47,b,11):'');
const title=s=>txt(20,29,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const sources={context:link('https://www.sci.gov.in/constitution/','Supreme Court: constitutional framework')+' · '+link('https://rajbhasha.gov.in/en/languages-included-eighth-schedule-indian-constitution','MHA:22 scheduled languages')+' · '+link('https://mausam.imd.gov.in/imd_latest/monsoonreport2024.pdf','IMD:2024 monsoon report')+'. Diversity and variable access; no single-factor prediction.',states:link(data.regions.source,'Economic Survey2025–26 Table1.11A')+'. 2023–24, current ₹ per person,2011–12series; source snapshot1August2025. NSDP is economic output, not wages or household disposable income. Selected states, not a national mean.',sectors:link(data.sectors.source,'NITI Aayog October2025, Table3.1 / NAS2025')+'. GVA at constant2011–12prices; earlier multi-year average versus one later year. Primary includes mining; knowledge services are within services, not an extra share. Not employment shares.',flows:link(data.partners.source,'Government economic-diplomacy report,18April2025')+' · '+link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth public-domain geometry')+'. Provisional FY 2024–25 merchandise exports; two selected destinations only. Approximate endpoints, generalised boundaries; width is value, not distance or a shipping route.',exports:link(data.exports.source,'Commerce Ministry / PIB,2May2025')+'. FY 2024–25 nominal gross exports; rounded US$billion. Goods437.4 derived from rounded824.9−387.5; different dated snapshot from partner flows. Not GDP or profits.',aid:link('https://www.mea.gov.in/development-partnership.htm','MEA development partnerships')+' · '+link('https://www.mea.gov.in/Lines-of-Credit-for-Development-Projects.htm','MEA concessional credit,August2024 snapshot')+' · '+link('https://www.worldbank.org/en/results/2020/10/16/unleashing-the-power-of-women-collectives-for-rural-development-in-the-indian-state-of-bihar','World Bank Bihar JEEViKA,2020')+'. Grants, credit and training differ; programme aims are not independently proven universal outcomes.',history:link('https://www.rbi.org.in/scripts/bs_viewcontent.aspx?Id=2253','RBI historical account:external-sector opening after1991')+'. Historical development, not current investment eligibility rules. Foreign investment does not measure all private investment.',capex:link(data.capex.source,'PIB3February2026:public capex budget estimates')+'. FY2025–26BE11.21 andFY2026–27BE12.2₹lakhcrore; nominal plans, not actual delivery or public/private shares.'};
const source=k=>`<p class="geo-caption">${sources[k]}</p>`;
const table=(caption,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${caption}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
export function indiaEconomyEvidence(k='states'){
 if(k==='states'){let b=title('INDIA · SELECTED STATE OUTPUT PER PERSON')+txt(20,52,'2023–24 · current ₹ · zero-based bars',11);for(const[i,[name,value]]of data.regions.states.entries()){const y=85+i*58;b+=txt(20,y,name,12)+`<rect x="20" y="${y+7}" width="${value/1000}" height="17" rx="3" fill="${i===1?'#edb194':'#9ebfb5'}"/>`+txt(365,y+22,fmt(value),11);}b+=path('M20 309H360','#b5cbd0',1)+txt(20,329,'0',10)+txt(285,329,'₹340,000',10);return fig(b,'Four selected Indian states, same economic-output measure and year. Bar lengths are proportional to current-price per-capita NSDP. Read the values before comparing.')+source('states')+table('2023–24 NSDP per person; source snapshot1August2025',['State','Current ₹'],data.regions.states.map(([n,v])=>[n,fmt(v)]));}
 if(k==='sectors'){const colours=['#edb194','#c8bb9e','#9ebfb5'];let b=title('INDIA · CONSTANT-PRICE ECONOMIC PROFILE')+txt(20,53,'% of GVA · each bar totals100%',11);for(const[i,[period,vals]]of data.sectors.periods.entries()){const y=100+i*110;b+=txt(20,y,period,12);let x=20;for(let j=0;j<3;j++){const w=vals[j]*4;b+=`<rect x="${x}" y="${y+13}" width="${w}" height="37" fill="${colours[j]}"/>`+`<text x="${x+w/2}" y="${y+37}" fill="#17334a" text-anchor="middle" font-size="12">${vals[j]}</text>`;x+=w;}}for(let j=0;j<3;j++)b+=`<rect x="${20+j*140}" y="290" width="12" height="12" fill="${colours[j]}"/>`+txt(38+j*140,301,data.sectors.categories[j],11);b+=txt(20,333,'Knowledge services sit within the services total.',11);return fig(b,'Matched-category GVA shares from NITI Aayog Table3.1. The earlier period is a three-year average; the later period is2023–24. Each displayed bar totals100%.')+source('sectors')+table('GVA shares at constant2011–12prices',['Period',...data.sectors.categories],data.sectors.periods.map(([p,v])=>[p,...v.map(n=>n+'%')]));}
 if(k==='flows'){let b=title('INDIA → TWO MERCHANDISE DESTINATIONS')+txt(20,51,'FY 2024–25 · US$billion · provisional 18 April 2025',10);for(const p of developmentPaths)b+=`<path d="${p.d}" fill="${p.code==='IND'?'#d8b294':['USA','CHN'].includes(p.code)?'#a8c0ac':'#587d80'}" stroke="#234355" stroke-width="0.4"/>`;b+=`<defs><marker id="d3-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="9" markerHeight="9" orient="auto-start-reverse" markerUnits="userSpaceOnUse"><path d="M0 0L10 5L0 10Z" fill="#f4c0a4"/></marker></defs>`;
 b+=`<path d="M306 142Q217 54 108 119" fill="none" stroke="#f0b395" stroke-opacity="0.86" stroke-width="${tradeWidth(86.51)}" marker-end="url(#d3-arrow)"/><path d="M310 141Q333 134 333 116" fill="none" stroke="#f0b395" stroke-width="${tradeWidth(14.2)}" marker-end="url(#d3-arrow)"/>`+dot(307,143,3)+txt(270,181,'India',12)+box(20,245,190,'USA: 86.51','Arrow points to destination')+box(230,245,190,'China: 14.2','Same width scale')+txt(20,336,'Width key: US$50bn',11)+path(`M175 331H245`,'#f0b395',tradeWidth(50));return fig(b,'Actual world country shapes with two selected export flow lines from India. Width is proportional to merchandise-export value on the same scale; curves show connections, not shipping routes.')+source('flows')+table('Provisional merchandise exports from India,FY 2024–25',['Destination','US$billion'],data.partners.flows);}
 const isCap=k==='capex',rows=isCap?data.capex.periods:[['Goods (rounded)',data.exports.goodsRounded],['Services',data.exports.services]],max=isCap?13:450;let b=title(isCap?'PUBLIC CAPEX · COMPARE BUDGET PLANS':'INDIA · GOODS AND SERVICES EXPORTS')+txt(20,54,isCap?'₹lakhcrore · budget estimates · nominal':'FY 2024–25 · rounded US$billion · nominal',11);for(const[i,[name,value]]of rows.entries()){const y=105+i*104;b+=txt(20,y,name,13)+`<rect x="20" y="${y+14}" width="${value/max*340}" height="28" rx="4" fill="${i?'#a8c2af':'#edb194'}"/>`+txt(30+value/max*340,y+35,String(value),12);}b+=txt(20,327,isCap?'BE = budget estimate, not actual delivered spending.':'Rounded totals; gross receipts, not GDP or profit.',11);return fig(b,isCap?'Two dated public capital-expenditure budget estimates on a common zero-based scale. Values describe planned nominal spending.':'Rounded exports in two categories using the2May2025 official release. Goods is the rounded difference between total824.9 and services387.5.')+source(isCap?'capex':'exports')+table(isCap?'Public capex budget estimates':'FY 2024–25 rounded exports',['Category',isCap?'₹lakhcrore':'US$billion'],rows);
}
export function indiaEconomyScene(k,v,t=0){if(!indiaEconomyViews[k])return '';if(!indiaEconomyRequirements[k].includes(v))v=indiaEconomyRequirements[k][0];t=indiaEconomyAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='context';
 if(k==='dev-india-regions'&&v==='evidence')return indiaEconomyEvidence('states');if(k==='dev-india-sectors'&&v==='profile')return indiaEconomyEvidence('sectors');if(k==='dev-india-trade-aid'&&['flows','exports'].includes(v))return indiaEconomyEvidence(v);if(k==='dev-india-investment'&&v==='evidence')return indiaEconomyEvidence('capex');
 if(k==='dev-india-context'){
 if(v==='institutions'){b=title('INDIA · A DIVERSE CONSTITUTIONAL SYSTEM')+box(20,70,190,'Union institutions','National policies')+box(230,70,190,'State institutions','Regional decisions')+path('M210 102H230')+box(20,180,400,'Different communities','Languages / religions / lived experiences')+txt(20,290,'22 scheduled languages ≠ every spoken language',12)+txt(20,322,'Access and representation influence participation.',11);c='Institutional and cultural context, not a chart of all government powers or a complete account of Indian society.';}
 else if(v==='access'){b=title('FROM AVAILABLE OPPORTUNITY TO USABLE ACCESS')+box(20,70,180,'Education / health','Capability and security')+box(240,70,180,'Transport / power','Reach and reliability')+box(115,245,210,'Work / services','Can different people participate?')+path('M110 138L180 235M330 138L260 235')+dot(110+70*t,138+97*t)+dot(330-70*t,138+97*t)+txt(20,330,'Possible enabling links, not measured national effects.',11);c='Supporting services can enable participation; access, affordability and skills influence who benefits. Moving tokens show relationships, not people counted.';}
 else if(v==='monsoon'){b=title('SEASONAL RAIN → WATER SUPPLY → LIVELIHOODS')+`<ellipse cx="100" cy="100" rx="68" ry="28" fill="#adc7cb"/>`+Array.from({length:7},(_,i)=>path(`M${50+i*17} ${140+t*45}l-5 12`,'#bddde3',2)).join('')+`<path d="M20 240Q100 202 180 240L210 300H20Z" fill="#7a9c8d"/><path d="M230 235H420V300H230Z" fill="#679caf"/>`+txt(40,278,'Farms',14)+txt(268,278,'Water storage',13)+path('M110 177L110 221M140 177L285 225')+dot(140+145*t,177+48*t)+box(20,55,400,'Timing, intensity and distribution vary')+txt(20,330,'Drought / flooding risks depend on exposure and protection.',10);c='Conceptual monsoon-water transfer, not a weather forecast, measured rainfall sequence or claim of uniform effects. Looping repeats the explanation, not a real season.';}
 else{b=title('CONNECT LOCAL CONTEXT TO WIDER SCALES')+box(20,70,180,'South Asian neighbours','Trade / cooperation')+box(240,70,180,'Wider world','Markets / culture / migration')+box(20,230,400,'India: varied places and communities','Institutions + skills + services + environment')+path('M110 138L175 220M330 138L265 220');c='A static connections framework, not measured trade values or a complete diplomatic map. Conditions interact rather than fixing a single development outcome.';}
 }
 if(k==='dev-india-regions'){s='states';
 if(v==='network'){b=title('CONNECTED ADVANTAGES CAN REINFORCE A HUB')+box(20,75,180,'Transport / networks','Reach markets')+box(240,75,180,'Firms / suppliers','Deeper demand')+box(125,245,190,'Skills / investment','More opportunities')+path('M205 108H233M330 146L260 236M125 275L80 145')+dot(205+28*t,108)+dot(330-70*t,146+90*t)+dot(125-45*t,275-130*t)+txt(20,330,'Core = economic influence, not geographic centre.',11);c='Cumulative advantage is a possible feedback mechanism. Mumbai and Bengaluru are major nodes; this toy sequence is not a measured growth model or a permanent regional label.';}
 else if(v==='spread'){b=title('SPREAD AND BACKWASH CAN OCCUR TOGETHER')+box(20,95,170,'Major hub','Concentrated demand')+box(250,95,170,'Other places','Skills / suppliers')+path('M190 115H245','#e9b499',3)+dot(190+55*t,115,5,'#e9b499')+path('M250 147H195','#a6c5b6',3)+dot(250-55*t,147,5,'#a6c5b6')+txt(20,207,'→ Contracts / remittances may spread benefits',11)+txt(20,236,'← Skills / capital may concentrate in the hub',11)+box(20,275,400,'Compare net effects','Connections and policy can change the balance');c='Conceptual opposing links, not proportional measured flows. Supply demand and remittances can spread gains; selective outmigration or investment concentration can weaken other places.';}
 else{b=title('A STATE MEAN DOES NOT DESCRIBE EVERYONE')+box(20,70,190,'Connected district','Jobs / reliable services')+box(230,70,190,'Underserved district','Access barriers remain')+box(20,185,400,'Inside the same state','Different households, opportunities and costs')+txt(20,292,'NSDP per person ≠ a payment to each resident',12)+txt(20,324,'Read distribution and access alongside the mean.',11);c='A conceptual within-state comparison, not actual district data. State averages can coexist with substantial internal inequalities.';}
 }
 if(k==='dev-india-sectors'){s='sectors';
 if(v==='classify'){b=title('ONE PRODUCT · FOUR TYPES OF ACTIVITY')+box(20,70,190,'Primary','Grow cotton')+box(230,70,190,'Secondary','Make cloth')+box(20,200,190,'Tertiary','Transport / sell')+box(230,200,190,'Quaternary','Research better materials')+path('M210 100H225M330 140L115 190M210 230H225')+txt(20,322,'Knowledge services are nested in published services.',11);c='An illustrative textile chain connecting four activity types; firms can contain several roles. The published GVA chart does not provide a separate quaternary share.';}
 else if(v==='chain'){const nodes=[[20,65,'Grow','Cotton'],[250,65,'Manufacture','Cloth'],[250,240,'Distribute','Retail'],[20,240,'Research','Improve process']];b=title('FOLLOW MATERIALS AND KNOWLEDGE');for(const[x,y,a,z]of nodes)b+=box(x,y,170,a,z);b+=path('M195 100H242M335 137V230M245 273H198M105 235V137')+dot(195+47*t,100)+dot(335,137+93*t)+dot(245-47*t,273)+dot(105,235-98*t)+txt(20,335,'Goods move forward; knowledge can improve earlier stages.',10);c='Symbolic sector connections and feedback, not a measured shipment or a claim that every worker moves through these sectors. Token timing represents sequence only.';}
 else{b=title('SECTOR CHANGE · GAINS AND COSTS')+box(20,65,400,'Primary: productivity / food','Water pressure / unequal access to equipment')+box(20,141,400,'Secondary: jobs / supply demand','Pollution / insecure work without safeguards')+box(20,217,400,'Tertiary + quaternary: access / expertise','Congestion / uneven skills and connectivity')+txt(20,324,'Judge distribution, working conditions and safeguards.',11);c='Potential benefits and costs across all four sectors, not identical effects in every region or a calculation of net national welfare.';}
 }
 if(k==='dev-india-trade-aid'){s=v==='aid'?'aid':'exports';
 if(v==='exchange'){b=title('TRADE · GOODS OR SERVICES FOR PAYMENT')+box(20,85,170,'India','Exporter in this example')+box(250,85,170,'Overseas buyer','Destination')+path('M195 102H242','#eeb79a',3)+dot(195+47*t,102,5,'#eeb79a')+path('M245 139H198','#aac8b8',3)+dot(245-47*t,139,5,'#aac8b8')+txt(20,210,'→ Product / service',14)+txt(20,245,'← Payment',14)+box(20,280,400,'Imports reverse the product direction');c='A commercial exchange sequence, not an aid grant or an actual shipping/payment schedule. India also imports goods and services; receipts are not profits.';}
 else{b=title('INDIA · DEVELOPMENT PARTNERSHIP ROLES')+box(20,65,190,'Recipient example','World Bank → Bihar groups')+box(230,65,190,'Provider examples','India → overseas partners')+box(20,210,190,'Grants / training','Resources / capability')+box(230,210,190,'Concessional credit','Favourable terms / repayment')+path('M115 140V200M325 140V200')+dot(115,140+60*t)+dot(325,140+60*t)+txt(20,328,'Forms and roles differ by programme; assess outcomes.',11);c='Different participation roles, not a single combined project or a proportional aid-flow chart. Credit differs from a gift; support and training do not alone prove lasting benefits.';}
 }
 if(k==='dev-india-investment'){s=v==='history'?'history':'capex';
 if(v==='history'){b=title('CHANGING ROLES · NOT A COMPLETE WITHDRAWAL')+box(20,65,400,'Earlier state-led planning','Public enterprises / controls / infrastructure')+box(20,150,400,'From 1991: wider private / foreign participation','Domestic firms / TNCs / smaller businesses')+box(20,235,400,'Public investment continues alongside firms','Networks / skills / services / regulation');c='A simplified historical transition supported by the RBI account. Opening to private participation did not abolish public investment; this is not a measured public/private share series.';}
 else if(v==='networks'){b=title('PUBLIC NETWORKS CAN ENABLE PRIVATE ACTIVITY')+box(20,75,190,'Public investment','Power / roads / skills')+box(250,75,170,'Private firms','Production / services')+box(125,245,190,'Local opportunities','Suppliers / jobs')+path('M215 108H242M335 146L260 235')+dot(215+27*t,108)+dot(335-75*t,146+89*t)+txt(20,330,'Access, reliability and demand determine actual effects.',11);c='A possible complementary investment sequence. Firms include TNCs and smaller domestic businesses; public projects can also compete for resources. This is not a causal effect estimate.';}
 else{const vals=Object.entries(localBudget),ys=[113,185,257],labels=['Local suppliers','Outside purchases','Upkeep'];b=title('FOLLOW 100 TEACHING UNITS · INVENTED BUDGET')+box(20,60,400,'Track where spending goes');for(let i=0;i<3;i++){const n=vals[i][1];b+=txt(20,ys[i],labels[i],12)+`<rect x="155" y="${ys[i]-17}" width="${n*3.6}" height="25" rx="3" fill="${i===1?'#d9b69b':'#a4c0b0'}"/>`+txt(165+n*3.6,ys[i]+1,String(n),12)+dot(155+n*3.6*t,ys[i]-5,3);}b+=txt(20,326,'60 local +25 outside +15 upkeep =100 total',12);c='Conserved illustrative spending allocation, not an actual TNC project, national multiplier or automatic welfare gain. Local procurement can spread demand; outside spending and upkeep have different roles.';}
 }
 return fig(b,c)+source(s);
}
